#!/usr/bin/env python3
"""Generate the `burn-fused` facade from the workspace member list.

The facade is 29 `pub use` lines and a feature list. Both were hand-maintained,
both rotted (13 crates declare `cuda`, the facade named 12, `burn-mor` was
missing and nobody noticed because nothing consumed the facade), so both are
generated from the manifests now. CI runs `--check`, which fails when a
member is added, renamed or given a new feature without regenerating.

    tools/gen_facade.py            # write
    tools/gen_facade.py --check    # exit 1 if the tree is not what we generate

Generated: `burn-fused/src/lib.rs` (whole file), and the block between the
markers in `burn-fused/Cargo.toml` and `burn-fused/tests/facade.rs`.
"""

from __future__ import annotations

import argparse
import pathlib
import sys
import tomllib

ROOT = pathlib.Path(__file__).resolve().parent.parent
FACADE = ROOT / "burn-fused"
# Markers are matched as substrings so the comment style (`#` in TOML, `//` in
# Rust) stays the file's own business.
BEGIN = "generated by tools/gen_facade.py"
END = "end generated"

# Burn crates the facade re-exports, so a user gets ONE version choice instead
# of 29 path deps that can each resolve a different `burn`. `feature` is the
# facade feature that turns the re-export on; the matching optional dependency
# is emitted into the same feature.
BACKEND_REEXPORTS = [
    ("burn_cuda", "cuda"),
    ("burn_autodiff", "autodiff"),
]

# Member features that are NOT part of the facade's public surface. Every other
# feature a member declares is propagated, so adding a feature to a member
# forces a decision here instead of silently not reaching users.
# feature -> why it stays private
NOT_PUBLIC = {
    "binary-tests": (
        "burn-gdn2 declares it as an empty marker for the fork's own "
        "GPU CI to build test binaries; nothing in the workspace reads it"
    ),
}


def load(path: pathlib.Path) -> dict:
    with path.open("rb") as f:
        return tomllib.load(f)


def members() -> list[dict]:
    """Every library member under `crates/`, with its features."""
    ws = load(ROOT / "Cargo.toml")
    out = []
    for entry in ws["workspace"]["members"]:
        entry = entry.strip()
        if not entry.startswith("crates/"):
            continue  # the facade itself and the bench harnesses
        manifest = load(ROOT / entry / "Cargo.toml")
        pkg = manifest["package"]
        lib = manifest.get("lib", {})
        name = pkg["name"]
        out.append(
            {
                "dir": entry,
                "name": name,
                "ident": lib.get("name", name).replace("-", "_"),
                "features": sorted(manifest.get("features", {})),
                "default": manifest.get("features", {}).get("default", []),
            }
        )
    return sorted(out, key=lambda m: m["name"])


def propagated(crates: list[dict]) -> list[str]:
    """The facade's feature names: the union of member features, minus the
    private ones and minus `default` (the facade re-derives its own default)."""
    names = {f for c in crates for f in c["features"]} - {"default"} - set(NOT_PUBLIC)
    return sorted(names)


def check_members(crates: list[dict]) -> list[str]:
    """Loud failures for the two ways this can rot silently."""
    public = set(propagated(crates))
    problems = []
    for c in crates:
        # The facade sets `default-features = false` per dependency and
        # re-derives the default itself, so a member's default features must
        # all be features the facade can name. `std` used to be ASSUMED rather
        # than checked: the check was `c["default"] != ["std"]`, so any member
        # that grew a second default feature made the generator refuse to run
        # instead of carrying it. That is what ff7cd57 hit, when it put
        # `binary-tests` into burn-gdn2's default to get the 1000-case
        # bit-exactness anchor and test_chunk back into the default cell.
        for f in c["default"]:
            if f not in public and f not in NOT_PUBLIC:
                problems.append(
                    f"{c['name']}: default feature {f!r} is not something the "
                    "facade can name (it sets default-features = false per dep "
                    "and re-derives the default), so a facade consumer would "
                    f"silently lose it. Add {f!r} to the facade's default, or "
                    "take it out of the member's default and require it "
                    "explicitly - NOT_PUBLIC says why it is not propagated."
                )
        for f in c["features"]:
            if f != "default" and f not in public and f not in NOT_PUBLIC:
                problems.append(f"{c['name']}: unhandled feature {f!r}")
    return problems


def facade_default(crates: list[dict]) -> list[str]:
    """The union of every member's DEFAULT features, sorted.

    This is what the facade's own `default` must be: it disables each
    dependency's defaults and re-enables them here, so a member default that
    is not re-enabled here is a feature a consumer of the facade silently does
    not get. Deriving it means a member can grow a default feature and the
    facade follows, instead of the generator refusing to run - but only
    features the facade can actually name may appear (check_members), because
    cargo rejects a `default` entry that is neither a dependency nor a feature
    this crate declares.
    """
    return sorted({f for c in crates for f in c["default"]})


def feature_table(crates: list[dict]) -> str:
    """[features]: every member feature, listing the members that declare it."""
    lines = [
        "[features]",
        'default = ["std"]',
        "",
        "# every member ships `std`; the facade default is exactly this.",
        "# a member default feature NOT listed here is one the facade does not",
        "# restore (see NOT_PUBLIC) - its owner must require it explicitly.",
    ]
    for feat in propagated(crates):
        on = [c for c in crates if feat in c["features"]]
        if feat == "std":
            lines.append("# every member ships `std`; the facade default is exactly this")
        lines.append(f"{feat} = [")
        for c in on:
            lines.append(f'    "{c["name"]}/{feat}",')
        for ident, on_feature in BACKEND_REEXPORTS:
            if on_feature == feat:
                lines.append(f'    "dep:{ident.replace("_", "-")}",')
        lines.append("]")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n"


def dep_table(crates: list[dict]) -> str:
    lines = ["[dependencies]"]
    for c in crates:
        lines.append(f'{c["name"]} = {{ path = "../{c["dir"]}", default-features = false }}')
    for ident, _ in BACKEND_REEXPORTS:
        dep = ident.replace("_", "-")
        lines.append(f"{dep} = {{ workspace = true, optional = true }}")
    lines += [
        "",
        "[dev-dependencies]",
        "# NdArray only: the facade's tests are CPU-only by design, so they run",
        '# next to a training run and need no GPU. `autodiff` is a facade',
        "# feature (it re-exports burn-autodiff for the members), not a test dep.",
        'burn = { workspace = true, features = ["ndarray", "extension"] }',
        'burn-ndarray = { workspace = true, features = ["blas-openblas"] }',
    ]
    return "\n".join(lines) + "\n"


def lib_rs(crates: list[dict]) -> str:
    out = [
        "//! # burn-fused",
        "//!",
        "//! One dependency for the whole fused-kernel workspace: every member",
        "//! crate is re-exported here, and the feature flags are derived from the",
        "//! members' own manifests. Both lists are GENERATED - run",
        "//! `tools/gen_facade.py` after adding a crate or a feature, and CI",
        "//! (`tools/gen_facade.py --check`) fails if you forget.",
        "//!",
        "//! Not affiliated with the official burn project. Every crate cites its",
        "//! paper source in its README.",
        "//!",
        "//! Re-exports are unconditional on purpose: a member behind a `cfg` could",
        "//! lose its `pub use` and still compile, which is exactly the rot this",
        "//! file exists to prevent. What the features control is each member's own",
        "//! runtime features, not whether the crate is reachable.",
        "//!",
        "//! Integration: `INTEGRATION.md` (this crate's README, and what CI",
        "//! compiles). Which backend types reach the fused kernels, which features",
        "//! exist, and the precision story per mechanism are all answered there.",
        "//!",
        "//! ```",
        "//! # fn main() {",
        "//! use burn::backend::NdArray;",
        "//! use burn::tensor::{Distribution, Tensor};",
        "//! use burn_fused::burn_kda::KdaModule;",
        "//!",
        "//! let device = Default::default();",
        "//! let x = Tensor::<3>::random([1, 16, 128], Distribution::Default, &device);",
        "//! let layer = KdaModule::new(&Default::default(), 0.0, &device);",
        "//! let y = layer.forward_train::<NdArray>(x);",
        "//! assert_eq!(y.dims(), [1, 16, 128]);",
        "//! # }",
        "//! ```",
        "",
    ]
    for ident, feat in BACKEND_REEXPORTS:
        out += [f'#[cfg(feature = "{feat}")]', f"pub use {ident};", ""]
    for c in crates:
        out.append(f"pub use {c['ident']};")
    return "\n".join(out).rstrip() + "\n"


def inventory(crates: list[dict]) -> str:
    """The `use` list the compile test resolves: one statement per re-export,
    so a failure names the exact line whose `pub use` went missing. (cfg is
    not allowed on a nested use-tree item, so these cannot be one group.)
    Sorted, and with the members' alphabetical order, because that is the
    order rustfmt wants: `cargo fmt --check` is a CI gate."""
    entries = [(c["ident"], None) for c in crates]
    entries += [(ident, feat) for ident, feat in BACKEND_REEXPORTS]
    out = [
        "// The list is never called - resolving the paths IS the test. A deleted",
        "// `pub use` in lib.rs turns one of these lines into a compile error.",
        "#[allow(unused_imports)]",
        "mod re_exports {",
    ]
    for ident, feat in sorted(entries):
        if feat:
            out.append(f'    #[cfg(feature = "{feat}")]')
        out.append(f"    use burn_fused::{ident};")
    out.append("}")
    return "\n".join(out)


def replace_block(text: str, block: str) -> str:
    """Swap the lines between the markers, keeping both marker lines verbatim."""
    lines = text.splitlines(keepends=True)
    try:
        begin = next(i for i, l in enumerate(lines) if BEGIN in l)
        end = next(i for i, l in enumerate(lines) if END in l)
    except StopIteration:
        raise SystemExit("generated markers missing; cannot update in place") from None
    return "".join(lines[: begin + 1]) + block + "\n" + "".join(lines[end:])


def wanted() -> dict[pathlib.Path, str]:
    crates = members()
    problems = check_members(crates)
    if problems:
        raise SystemExit(
            "gen_facade: the manifests and the generator disagree:\n  "
            + "\n  ".join(problems)
        )
    lib = lib_rs(crates)
    manifest = (FACADE / "Cargo.toml").read_text()
    test = (FACADE / "tests" / "facade.rs").read_text()
    return {
        FACADE / "src" / "lib.rs": lib,
        FACADE / "Cargo.toml": replace_block(
            manifest, feature_table(crates) + "\n" + dep_table(crates)
        ),
        FACADE / "tests" / "facade.rs": replace_block(test, inventory(crates)),
    }


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument(
        "--check",
        action="store_true",
        help="exit 1 if any generated file is stale (used by CI and by a test)",
    )
    ap.add_argument(
        "--cuda-matrix",
        action="store_true",
        help="print `<crate> <features>` per line for every member that declares "
        "`cuda`, and exit - the input to CI job `cuda-compiles`, which used to "
        "carry a hand-written list of 13 crates",
    )
    args = ap.parse_args()
    if args.cuda_matrix:
        # Why this exists, in one line: the job's list named `burn-mor`, which
        # does not declare `cuda`, and asked `cuda,autodiff` of four crates
        # that do not declare `autodiff`. Cargo rejects a feature a package does
        # not have (it is not the "silent no-op" the old comment claimed), so the
        # loop died on the fourth crate and the nine behind it were never
        # checked. Derived from the manifests, it cannot rot.
        for m in members():
            if "cuda" not in m["features"]:
                continue
            combos = [["cuda"]]
            if "autodiff" in m["features"]:
                combos.append(["cuda", "autodiff"])
            for combo in combos:
                print(m["name"], ",".join(combo))
        return 0
    stale = []
    for path, text in wanted().items():
        current = path.read_text() if path.exists() else None
        if current == text:
            continue
        stale.append(path)
        if not args.check:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(text)
    if args.check and stale:
        for p in stale:
            print(f"stale: {p.relative_to(ROOT)} (run tools/gen_facade.py)", file=sys.stderr)
        return 1
    if stale:
        for p in stale:
            print(f"wrote: {p.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
